use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let data = input.as_array().unwrap();
    let mut result = Vec::new();
    let mut last_value = None;

    for row in data {
        let key = row[0].as_i64().unwrap();
        let value = row[1].as_i64().unwrap();
        if let Some(last_value) = last_value {
            if last_value == value {
                result.push(Value::from(vec![key, value]));
            } else {
                result.push(Value::from(vec![key, value]));
                last_value = Some(value);
            }
        } else {
            result.push(Value::from(vec![key, value]));
            last_value = Some(value);
        }
    }

    Value::from(result)
}
